import java.util.Random;

public class GaussianMutator {

    public static double mutateValue(Random rng, double value, double stdDevFactor, double min, double max) {
        double range = max - min;
        double stdDev = range * stdDevFactor;
        double mutated;
        do {
            mutated = value + rng.nextGaussian() * stdDev;
        } while (mutated < min || mutated > max);
        return mutated;
