    public static List<Double> discreteValuesInRange(double min, double max, int steps) {
        List<Double> values = new ArrayList<>();
        if (steps <= 1) {
            values.add(min);
            return values;
        }
        double step = (max - min) / (steps - 1);
        for (int i = 0; i < steps; i++) {
            values.add(min + i * step);
        }
        return values;
    }

    public static double[] mutateWithDiscreteValues(Random rng, double value, double stdDevFactor, double min, double max, int steps) {
        double mutated = mutateValue(rng, value, stdDevFactor, min, max);
        List<Double> discrete = discreteValuesInRange(min, max, steps);
        double closest = discrete.stream()
            .min((a, b) -> Double.compare(Math.abs(a - mutated), Math.abs(b - mutated)))
            .orElse(mutated);
        return new double[]{mutated, closest};
