        double mutated;
        do {
            mutated = value + rng.nextGaussian() * stdDev;
        } while (mutated < min || mutated > max);
        return mutated;
    }

    public static List<Double> discreteValuesInRange(double min, double max, int steps) {
        List<Double> values = new ArrayList<>();
        if (steps <= 1) {
            values.add(min);
            return values;
        }
        double step = (max - min) / (steps - 1);
        for (int i = 0; i < steps; i++) {
            values.add(min + i * step);
        }
        return values;
    }

