import org.apache.lucene.search.SortField;
import org.elasticsearch.index.fielddata.IndexFieldData;
import org.elasticsearch.index.fielddata.LeafFieldData;
import org.elasticsearch.index.fielddata.SortedBinaryDocValues;
import org.elasticsearch.index.fielddata.SortedNumericDoubleValues;
import org.elasticsearch.index.fielddata.plain.SortedNumericIndexFieldData;

import java.io.IOException;
import java.util.Arrays;
import java.util.Random;

public class FieldDataComparator {

    @FunctionalInterface
    public interface Preprocessor {
        double process(double value);
    }

    public static SortedBinaryDocValues compareAndLoad(
            Random random,
            LeafReaderContext context,
            IndexFieldData<?> fieldData1,
            IndexFieldData<?> fieldData2,
            Preprocessor preprocessor) throws IOException {

        LeafFieldData leafData1 = fieldData1.load(context);
        LeafFieldData leafData2 = fieldData2.load(context);

        SortedBinaryDocValues binaryValues1 = leafData1.getBytesValues();
        SortedBinaryDocValues binaryValues2 = leafData2.getBytesValues();

        int maxDoc = context.reader().maxDoc();
        byte[][][] results = new byte[maxDoc][][];

        for (int docId = 0; docId < maxDoc; docId++) {
            if (binaryValues1.advanceExact(docId) && binaryValues2.advanceExact(docId)) {
                int count1 = binaryValues1.docValueCount();
                int count2 = binaryValues2.docValueCount();

                double[] values1 = new double[count1];
                double[] values2 = new double[count2];

                for (int i = 0; i < count1; i++) {
                    org.apache.lucene.util.BytesRef ref = binaryValues1.nextValue();
                    values1[i] = preprocessor.process(bytesToDouble(ref.bytes, ref.offset));
                }

                for (int i = 0; i < count2; i++) {
                    org.apache.lucene.util.BytesRef ref = binaryValues2.nextValue();
                    values2[i] = preprocessor.process(bytesToDouble(ref.bytes, ref.offset));
                }

                Arrays.sort(values1);
                Arrays.sort(values2);

                int matchCount = 0;
                double[] matched = new double[Math.min(count1, count2)];

                for (double v1 : values1) {
                    int idx = Arrays.binarySearch(values2, v1);
                    if (idx >= 0) {
                        matched[matchCount++] = v1;
                    }
                }

                results[docId] = new byte[matchCount][];
                for (int i = 0; i < matchCount; i++) {
                    results[docId][i] = doubleToBytes(matched[i]);
                }
            } else {
                results[docId] = new byte[0][];
            }
        }

        return new SortedBinaryDocValues() {
            private int currentDoc = -1;
            private int currentOrd = 0;

            @Override
            public boolean advanceExact(int doc) throws IOException {
                currentDoc = doc;
                currentOrd = 0;
                return results[doc] != null && results[doc].length > 0;
            }

            @Override
            public int docValueCount() {
                return results[currentDoc] != null ? results[currentDoc].length : 0;
            }

            @Override
            public org.apache.lucene.util.BytesRef nextValue() throws IOException {
                byte[] val = results[currentDoc][currentOrd++];
                return new org.apache.lucene.util.BytesRef(val);
            }
        };
    }

    private static double bytesToDouble(byte[] bytes, int offset) {
        if (bytes.length - offset < 8) {
            return 0.0;
        }
        long bits = 0;
        for (int i = 0; i < 8; i++) {
            bits = (bits << 8) | (bytes[offset + i] & 0xFF);
        }
        return Double.longBitsToDouble(bits);
    }

    private static byte[] doubleToBytes(double value) {
        long bits = Double.doubleToLongBits(value);
        byte[] bytes = new byte[8];
        for (int i = 7; i >= 0; i--) {
            bytes[i] = (byte) (bits & 0xFF);
            bits >>= 8;
        }
        return bytes;
    }
}
