import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class ChannelConnectionManager {

    public void connectToRemote(String host, int port) throws IOException {
        Selector selector = Selector.open();
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);

        InetSocketAddress remoteAddress = new InetSocketAddress(host, port);
        boolean connected = socketChannel.connect(remoteAddress);

        if (connected) {
            handleConnected(socketChannel);
        } else {
            socketChannel.register(selector, SelectionKey.OP_CONNECT);
            processConnectionEvents(selector, socketChannel);
        }
    }

    private void processConnectionEvents(Selector selector, SocketChannel socketChannel) throws IOException {
        boolean running = true;

        while (running) {
            int readyChannels = selector.select(5000);

            if (readyChannels == 0) {
                System.out.println("Connection timeout - no events received.");
                running = false;
                break;
            }

            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();
                keyIterator.remove();

                if (key.isConnectable()) {
                    handleConnectableKey(key);
                    running = false;
                }
            }
        }

        selector.close();
    }

    private void handleConnectableKey(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();

        try {
            if (channel.isConnectionPending()) {
                boolean finishedConnecting = channel.finishConnect();

                if (finishedConnecting) {
                    System.out.println("Connection established to: " + channel.getRemoteAddress());
                    key.interestOps(SelectionKey.OP_READ | SelectionKey.OP_WRITE);
                    handleConnected(channel);
                } else {
                    System.out.println("Connection still pending...");
                }
            }
        } catch (IOException e) {
            System.err.println("Connection failed: " + e.getMessage());
            key.cancel();
            channel.close();
            handleConnectionFailed(e);
