    public ObjectLoader() {
        setTitle("Object Loader");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new GridLayout(4, 2, 10, 10));

        nameLabel = new JLabel("Name:");
        nameField = new JTextField();
        nameField.setEditable(false);

        valueLabel = new JLabel("Value:");
        valueField = new JTextField();
        valueField.setEditable(false);

        loadButton = new JButton("Load Object");
        statusLabel = new JLabel("No object loaded");

        add(nameLabel);
        add(nameField);
        add(valueLabel);
        add(valueField);
        add(loadButton);
        add(statusLabel);

        loadButton.addActionListener(e -> loadSerializedObject());

        pack();
        setSize(400, 200);
        setLocationRelativeTo(null);
    }

    public void loadSerializedObject() {
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Select Serialized Object File");
        fileChooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter(
            "Serialized files (*.ser)", "ser"));

        int result = fileChooser.showOpenDialog(this);
        if (result != JFileChooser.APPROVE_OPTION) {
            return;
        }

        File selectedFile = fileChooser.getSelectedFile();

        try (FileInputStream fis = new FileInputStream(selectedFile);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

            Object loadedObject = ois.readObject();
            updateGUIComponents(loadedObject);
            statusLabel.setText("Loaded: " + selectedFile.getName());

        } catch (FileNotFoundException ex) {
            showError("File not found: " + ex.getMessage());
        } catch (InvalidClassException ex) {
            showError("Incompatible class version: " + ex.getMessage());
        } catch (ClassNotFoundException ex) {
            showError("Class not found: " + ex.getMessage());
        } catch (IOException ex) {
            showError("IO error reading file: " + ex.getMessage());
        }
    }

    private void updateGUIComponents(Object obj) {
        if (obj instanceof SerializableData data) {
            nameField.setText(data.getName() != null ? data.getName() : "");
            valueField.setText(data.getValue() != null ? data.getValue().toString() : "");
        } else {
            nameField.setText(obj.getClass().getSimpleName());
            valueField.setText(obj.toString());
        }
    }

