        double maxFinalProb = Double.NEGATIVE_INFINITY;
        int maxFinalState = 0;
        for (int i = 0; i < N; i++) {
            if (dp[T-1][i] > maxFinalProb) {
                maxFinalProb = dp[T-1][i];
                maxFinalState = i;
            }
        }

        List<String> tagSequence = new ArrayList<>(Collections.nCopies(T, ""));
        tagSequence.set(T-1, states.get(maxFinalState));

        int currentState = maxFinalState;
        for (int t = T-2; t >= 0; t--) {
            currentState = backpointer[t+1][currentState];
            tagSequence.set(t, states.get(currentState));
        }

        return tagSequence;
    }

    private double getEmissionProb(String state, String word) {
        Map<String, Double> stateEmissions = emissionProbs.get(state);
        if (stateEmissions != null) {
            if (stateEmissions.containsKey(word)) {
                return stateEmissions.get(word);
            }
            String lowerWord = word.toLowerCase();
            if (stateEmissions.containsKey(lowerWord)) {
                return stateEmissions.get(lowerWord);
            }
        }
        return Math.log(1e-10);
    }

    private double getTransitionProb(String fromState, String toState) {
        Map<String, Double> stateTransitions = transitionProbs.get(fromState);
        if (stateTransitions != null && stateTransitions.containsKey(toState)) {
            return stateTransitions.get(toState);
        }
        return Math.log(1e-10);
    }

    public Map<String, String> tagText(String text) {
        List<String> tokens = tokenize(text);
        List<String> tags = viterbi(tokens);

        Map<String, String> taggedWords = new LinkedHashMap<>();
        for (int i = 0; i < tokens.size(); i++) {
            taggedWords.put(tokens.get(i), tags.get(i));
        }
        return taggedWords;
    }

    public List<Map.Entry<String, String>> tagTextOrdered(String text) {
        List<String> tokens = tokenize(text);
        List<String> tags = viterbi(tokens);

        List<Map.Entry<String, String>> result = new ArrayList<>();
        for (int i = 0; i < tokens.size(); i++) {
            result.add(new AbstractMap.SimpleEntry<>(tokens.get(i), tags.get(i)));
        }
        return result;
    }

    private List<String> tokenize(String text) {
        List<String> tokens = new ArrayList<>();
        String[] words = text.split("\\s+");
        for (String word : words) {
            word = word.replaceAll("^[^a-zA-Z0-9']+|[^a-zA-Z0-9']+$", "");
            if (!word.isEmpty()) {
                tokens.add(word);
            }
        }
        return tokens;
    }

