        thumbnailLabel.setIcon(null);

        SwingWorker<ImageIcon, Void> worker = new SwingWorker<>() {
            @Override
            protected ImageIcon doInBackground() throws Exception {
                String thumbnailUrl = "https://img.youtube.com/vi/" + videoId + "/hqdefault.jpg";
                URL url = new URL(thumbnailUrl);
                Image img = ImageIO.read(url);
                if (img != null) {
                    img = img.getScaledInstance(854, 480, Image.SCALE_SMOOTH);
                    return new ImageIcon(img);
                }
                return null;
            }

            @Override
            protected void done() {
                try {
                    ImageIcon icon = get();
                    if (icon != null) {
                        thumbnailLabel.setIcon(icon);
                        thumbnailLabel.setText("");
                    } else {
                        thumbnailLabel.setText("Could not load thumbnail. Click play to open.");
                        thumbnailLabel.setIcon(null);
                    }
                } catch (Exception ex) {
                    thumbnailLabel.setText("Could not load thumbnail. Click play to open.");
                }
                thumbnailLabel.revalidate();
                thumbnailLabel.repaint();
            }
        };

        worker.execute();
    }

    private void openVideoInBrowser() {
        try {
            String url = "https://www.youtube.com/watch?v=" + videoId;
            Desktop.getDesktop().browse(new java.net.URI(url));
        } catch (Exception ex) {
            JOptionPane.showMessageDialog(this, "Could not open browser: " + ex.getMessage(),
                    "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

