    public HttpResponse<String> sendPost(String endpoint, String requestBody, String token,
                                          boolean gzip, Integer maxRate) throws IOException, InterruptedException {
        if (maxRate != null && maxRate > 0) {
            this.rateLimiter = new Semaphore(maxRate);
